// This code has been fully generated by an AI.

package web

import (
	"context"
	"errors"
	"sync"
	"time"

	"github.com/stefanluchs/my-velo/internal/importer"
)

// ErrJobRunning is returned when an import is started while another runs.
var ErrJobRunning = errors.New("an import is already running")

// maxJobResults bounds memory for very large imports; stats stay complete.
const maxJobResults = 5000

// ImportJob is the state of one background import.
type ImportJob struct {
	Label      string
	StartedAt  time.Time
	FinishedAt time.Time
	Running    bool
	Stats      importer.Stats
	Results    []importer.Result
	Truncated  bool
	Error      string
}

// Jobs runs one import at a time in the background and keeps the state of
// the latest import for the status view.
type Jobs struct {
	ctx  context.Context
	mu   sync.Mutex
	last *ImportJob
	wg   sync.WaitGroup
}

// NewJobs creates a runner whose jobs are cancelled when ctx ends.
func NewJobs(ctx context.Context) *Jobs { return &Jobs{ctx: ctx} }

// Start runs fn in the background. fn reports each result via report.
// cleanup, if set, runs after fn finished, e.g. to remove uploaded files.
func (j *Jobs) Start(label string, fn func(ctx context.Context, report func(importer.Result)) error, cleanup func()) error {
	j.mu.Lock()
	defer j.mu.Unlock()
	if j.last != nil && j.last.Running {
		return ErrJobRunning
	}
	job := &ImportJob{Label: label, StartedAt: time.Now(), Running: true}
	j.last = job
	j.wg.Add(1)
	go func() {
		defer j.wg.Done()
		if cleanup != nil {
			defer cleanup()
		}
		err := fn(j.ctx, func(r importer.Result) {
			j.mu.Lock()
			defer j.mu.Unlock()
			job.Stats.Add(r)
			if len(job.Results) < maxJobResults {
				job.Results = append(job.Results, r)
			} else {
				job.Truncated = true
			}
		})
		j.mu.Lock()
		defer j.mu.Unlock()
		job.Running, job.FinishedAt = false, time.Now()
		if err != nil {
			job.Error = err.Error()
		}
	}()
	return nil
}

// Last returns a snapshot of the latest job, or nil if none ran yet.
func (j *Jobs) Last() *ImportJob {
	j.mu.Lock()
	defer j.mu.Unlock()
	if j.last == nil {
		return nil
	}
	cp := *j.last
	cp.Results = append([]importer.Result(nil), j.last.Results...)
	return &cp
}

// Wait blocks until running jobs have finished (used on shutdown and in tests).
func (j *Jobs) Wait() { j.wg.Wait() }
